package io.github.campione01.mineclientbridge;
import com.google.gson.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import static io.github.campione01.mineclientbridge.RetainedAdmissionStopChecks.*;
/** Exact production Gson UTF-8 limits and final BridgeJson envelopes; offline only. */
public final class StopProofBoundaryChecks {
 static int checks;
 static void ok(boolean value,String why){checks++;if(!value)throw new AssertionError(why);}
 static void refuses(Runnable work,String reason){checks++;try{work.run();throw new AssertionError("Expected refusal: "+reason);}catch(IllegalArgumentException expected){if(!reason.equals(expected.getMessage()))throw expected;}}
 static JsonObject padded(JsonObject retained,int extra){JsonObject j=retained.deepCopy(),row=new JsonObject();row.addProperty("id",Integer.MAX_VALUE);row.addProperty("uuid","ffffffff-ffff-4fff-8fff-ffffffffffff");row.addProperty("type","minecraft:removed_boundary_fixture");row.addProperty("class","BoundaryFixture"+"p".repeat(extra));row.addProperty("removed",true);j.getAsJsonArray("rows").add(row);j.addProperty("enumerated_count",j.get("enumerated_count").getAsInt()+1);j.addProperty("removed_count",j.get("removed_count").getAsInt()+1);return j;}
 static int wireBytes(JsonObject j)throws Exception{return BridgeJson.toJson(j).getBytes(StandardCharsets.UTF_8).length;}
 static void padWire(JsonObject object,int target)throws Exception{object.addProperty("boundary_padding","");int fill=target-wireBytes(object);ok(fill>=0,"padding has space");object.addProperty("boundary_padding","x".repeat(fill));ok(wireBytes(object)==target,"exact wire target "+target);}
 static void removeTerminal(JsonObject action){action.addProperty("status","running");action.addProperty("reason","accepted");action.addProperty("ticks",0);action.addProperty("input_owner","action");JsonObject r=action.getAsJsonObject("result");r.remove("route_threat_stop");r.remove("local_segment");r.remove("input_release_confirmed");}
 static void addTerminal(JsonObject action,JsonObject proof,JsonObject terminal){action.addProperty("status","cancelled");action.addProperty("reason","capability_threat_observed");action.addProperty("input_owner","direct");JsonObject r=action.getAsJsonObject("result");r.add("route_threat_stop",proof.deepCopy());r.add("local_segment",terminal.deepCopy());r.addProperty("input_release_confirmed",true);}
 static JsonObject maximumMetadata(JsonObject realTerminal)throws Exception{
  JsonObject terminal=realTerminal.deepCopy();for(var e:realTerminal.entrySet()){var v=e.getValue();if(v.isJsonPrimitive()&&v.getAsJsonPrimitive().isNumber())terminal.addProperty(e.getKey(),e.getKey().equals("sampled_horizontal_distance")?Double.MAX_VALUE:Long.MIN_VALUE);else if(e.getKey().endsWith("_nano"))terminal.addProperty(e.getKey(),Long.toString(Long.MIN_VALUE));}terminal.addProperty("phase","falling");
  JsonObject budget=new JsonObject();budget.addProperty("padding","");budget.addProperty("padding","x".repeat(4096-bytes(budget)));ok(bytes(budget)==4096,"conservative full ledger bound");
  JsonObject metadata=new JsonObject();metadata.add("local_segment",terminal);metadata.add("movement_budget",budget);for(String name:new String[]{"x","y","z"})metadata.addProperty(name,-Double.MAX_VALUE);metadata.addProperty("input_release_confirmed",false);metadata.addProperty("requested_terminal_status","cancelled");metadata.addProperty("requested_terminal_reason","capability_threat_observed");
  ok(bytes(metadata)<8192-128,"all terminal members plus key/status/tick growth fit original reserve");return metadata;
 }
 static void addMetadata(JsonObject action,JsonObject metadata){for(var e:metadata.entrySet())action.getAsJsonObject("result").add(e.getKey(),e.getValue().deepCopy());action.addProperty("ticks",159);action.addProperty("reason","route_spatial_stop_evidence_too_large");}
 public static void main(String[] args)throws Exception{
  Path out=Path.of(args[1]);Files.createDirectory(out);JsonObject retained=findGuard(JsonParser.parseString(Files.readString(Path.of(args[0]))));JsonObject zero=padded(retained,0);int baseProof=bytes(frame(zero).stop(true)),baseFrame=bytes(frame(zero).json());JsonArray boundaries=new JsonArray();JsonObject maximumProof=null;
  for(int n:new int[]{32767,32768,32769}){var candidate=frame(padded(retained,n-baseProof));JsonObject row=new JsonObject();row.addProperty("expected_complete_proof_bytes",n);row.addProperty("guard_bytes",bytes(candidate.json()));if(n<=32768){JsonObject proof=candidate.stop(true);ok(bytes(proof)==n,"exact complete proof size");row.addProperty("accepted",true);if(n==32768)maximumProof=proof;}else{refuses(()->candidate.stop(true),"route_spatial_stop_evidence_too_large");row.addProperty("accepted",false);}boundaries.add(row);}
  JsonObject unicode=padded(retained,32768-baseProof);JsonObject pad=unicode.getAsJsonArray("rows").get(unicode.getAsJsonArray("rows").size()-1).getAsJsonObject();String before=pad.get("class").getAsString();pad.addProperty("class",before.substring(0,before.length()-3)+"界");ok(bytes(frame(unicode).stop(true))==32768,"UTF-8 bytes not Java characters");pad.addProperty("class",pad.get("class").getAsString()+"x");refuses(()->frame(unicode).stop(true),"route_spatial_stop_evidence_too_large");
  JsonObject largeEnvelope=retained.deepCopy();for(var e:largeEnvelope.getAsJsonArray("rows")){var r=e.getAsJsonObject();if(r.has("native_living")){var n=r.getAsJsonObject("native_living");n.addProperty("world_generation",n.get("world_generation").getAsString()+"w".repeat(8000));}}var envelope=frame(largeEnvelope);ok(bytes(envelope.json())<32768,"guard fits but repeated envelope strings do not");refuses(()->envelope.stop(true),"route_spatial_stop_evidence_too_large");
  for(int n:new int[]{196607,196608,196609}){var candidate=frame(padded(retained,n-baseFrame));if(n<=196608)ok(bytes(candidate.json())==n,"general frame remains 192KiB");else refuses(candidate::json,"route_spatial_evidence_too_large");}
  int growth=ScopedRouteThreatPolicy.STOP_GROWTH_BYTES,limit=262144;
  for(int d:new int[]{-1,0})ScopedRouteThreatPolicy.requireResponseSizes(limit-growth+d,limit-3*growth+d,limit);
  refuses(()->ScopedRouteThreatPolicy.requireResponseSizes(limit-growth+1,limit-3*growth,limit),"scoped_movement_response_evidence_too_large");refuses(()->ScopedRouteThreatPolicy.requireResponseSizes(limit-growth,limit-3*growth+1,limit),"scoped_movement_response_evidence_too_large");
  JsonObject actual=JsonParser.parseString(Files.readString(Path.of(args[2]).resolve("generated-coherent.json"))).getAsJsonObject();JsonObject action=actual.getAsJsonObject("action").deepCopy(),terminal=action.getAsJsonObject("result").getAsJsonObject("local_segment").deepCopy();removeTerminal(action);
  JsonObject standalone=WireV1Fixture.actionEndpoint(action,true);JsonObject coherent=actual.deepCopy();removeTerminal(coherent.getAsJsonObject("action"));removeTerminal(coherent.getAsJsonObject("status").getAsJsonObject("client_action"));removeTerminal(coherent.getAsJsonObject("state").getAsJsonObject("client_action"));
  padWire(standalone,limit-growth);padWire(coherent,limit-3*growth);ScopedRouteThreatPolicy.requireResponseSizes(wireBytes(standalone),wireBytes(coherent),limit);
  // These transport-only envelopes exercise the real complete-size caps. The
  // maximum-proof identity came from retained evidence, not the synthetic action;
  // they are not semantic consumer fixtures and must never authorize defense.
  addTerminal(standalone,maximumProof,terminal);addTerminal(coherent.getAsJsonObject("action"),maximumProof,terminal);addTerminal(coherent.getAsJsonObject("status").getAsJsonObject("client_action"),maximumProof,terminal);addTerminal(coherent.getAsJsonObject("state").getAsJsonObject("client_action"),maximumProof,terminal);
  int finalOne=wireBytes(standalone),finalAll=wireBytes(coherent);ok(finalOne<=limit,"max admitted standalone with complete max proof fits");ok(finalAll<=limit,"max admitted coherent with three complete max proofs fits");
  JsonObject maximumMetadata=maximumMetadata(terminal);addMetadata(standalone,maximumMetadata);addMetadata(coherent.getAsJsonObject("action"),maximumMetadata);addMetadata(coherent.getAsJsonObject("status").getAsJsonObject("client_action"),maximumMetadata);addMetadata(coherent.getAsJsonObject("state").getAsJsonObject("client_action"),maximumMetadata);int conservativeOne=wireBytes(standalone),conservativeAll=wireBytes(coherent);ok(conservativeOne<=limit,"conservative complete standalone growth fits");ok(conservativeAll<=limit,"conservative complete coherent growth fits");
  JsonObject report=new JsonObject();report.addProperty("assertions",checks);report.add("complete_proof_boundaries",boundaries);report.addProperty("full_stop_max",32768);report.addProperty("stop_growth",growth);report.addProperty("standalone_admission_max",limit-growth);report.addProperty("capability_admission_max",limit-3*growth);report.addProperty("standalone_terminal_at_boundary_bytes",finalOne);report.addProperty("capability_terminal_at_boundary_bytes",finalAll);report.addProperty("conservative_terminal_metadata_bytes",bytes(maximumMetadata));report.addProperty("conservative_standalone_at_boundary_bytes",conservativeOne);report.addProperty("conservative_capability_at_boundary_bytes",conservativeAll);report.addProperty("scope","Exact real Gson/BridgeJson UTF-8 boundary checks; real controller terminal plus separate conservative numeric/ledger metadata bound; padded transport envelopes are not semantically valid consumer receipts.");write(out.resolve("boundary-result.json"),report);System.out.println(WIRE.toJson(report));
 }
}
